after.content:
if ($LASTEXITCODE -ne 0) { throw "Stage 0-2 regression gate failed: $LASTEXITCODE" }
& .\gradlew.bat :ji-acp-v2-preview-model:test :ji-acp-v2-preview-server:test :ji-acp-v1-server:runJavaClientConformance :ji-cli:installDist --offline --rerun-tasks --no-daemon
if ($LASTEXITCODE -ne 0) { throw "Stage 3 Java/preview/client gate failed: $LASTEXITCODE" }
& corepack pnpm --offline check:acp-v1:typescript-client -- .\build\stage3-typescript-client.json
if ($LASTEXITCODE -ne 0) { throw "TypeScript client conformance failed: $LASTEXITCODE" }
& node .\tooling\acp-conformance\run-acpx-smoke.mjs .\build\stage3-acpx.json
if ($LASTEXITCODE -ne 0) { throw "acpx interaction smoke failed: $LASTEXITCODE" }
& node .\tooling\acp-conformance\run-gold-band-smoke.mjs .\build\stage3-gold-band.json
if ($LASTEXITCODE -ne 0) { throw "Gold-Band interaction smoke failed: $LASTEXITCODE" }
& node .\scripts\verify-api-baseline.mjs
if ($LASTEXITCODE -ne 0) { throw "API baseline verification failed: $LASTEXITCODE" }
